/**
 * Regression guard for ruvnet/ruflo#1906 — model aliases must map to
 * current (Claude 4.x) model ids, not the deprecated Claude-3.x ids that
 * the Anthropic API now 404s.
 */
import { describe, it, expect } from 'vitest';
import { resolveAnthropicModel, DEFAULT_ANTHROPIC_MODEL } from '../src/mcp-tools/agent-execute-core.js';

describe('#1906 — agent_execute model aliases resolve to current Claude 4.x ids', () => {
  it('haiku → claude-haiku-4-5-20251001', () => {
    expect(resolveAnthropicModel('haiku')).toBe('claude-haiku-4-5-20251001');
  });
  it('sonnet → claude-sonnet-4-6', () => {
    expect(resolveAnthropicModel('sonnet')).toBe('claude-sonnet-4-6');
  });
  it('opus → claude-opus-4-8 (#2232 alias bump)', () => {
    expect(resolveAnthropicModel('opus')).toBe('claude-opus-4-8');
  });
  it('opus-4.7 reaches the prior pin', () => {
    expect(resolveAnthropicModel('opus-4.7')).toBe('claude-opus-4-7');
  });
  it('inherit → the default (sonnet 4.6)', () => {
    expect(resolveAnthropicModel('inherit')).toBe('claude-sonnet-4-6');
    expect(DEFAULT_ANTHROPIC_MODEL).toBe('claude-sonnet-4-6');
  });
  it('undefined → the default', () => {
    expect(resolveAnthropicModel(undefined)).toBe(DEFAULT_ANTHROPIC_MODEL);
  });
  it('anthropic:<id> prefix is stripped', () => {
    expect(resolveAnthropicModel('anthropic:claude-opus-4-7')).toBe('claude-opus-4-7');
  });
  it('a bare model id passes through unchanged', () => {
    expect(resolveAnthropicModel('claude-sonnet-4-6')).toBe('claude-sonnet-4-6');
  });
  it('no alias resolves to a deprecated claude-3.x id (#1906 regression)', () => {
    for (const alias of ['haiku', 'sonnet', 'opus', 'inherit', undefined]) {
      expect(resolveAnthropicModel(alias as string | undefined)).not.toMatch(/^claude-3[.-]/);
    }
  });
});

/**
 * Regression guard for ruvnet/ruflo#1916.
 *
 *  (a) `agent_logs` MCP tool must be registered — the `ruflo agent logs <id>`
 *      CLI subcommand called `callMCPTool('agent_logs', …)` against a tool
 *      that didn't exist → `MCP tool not found: agent_logs`.
 *  (b) `agent_status` / `agent_list` / `agent_logs` must resolve hive-mind-
 *      spawned workers — `hive-mind_spawn` writes workers to
 *      `.claude-flow/agents.json`, a *different* file from the canonical
 *      `.claude-flow/agents/store.json` the agent tools read, so
 *      `agent status <hive-worker-id>` returned `not_found`.
 */
import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { mkdtempSync, mkdirSync, writeFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { agentTools } from '../src/mcp-tools/agent-tools.js';

const tool = (name: string) => {
  const t = agentTools.find(t => t.name === name);
  if (!t) throw new Error(`MCP tool not registered: ${name}`);
  return t;
};

describe('#1916 — agent_logs registered + hive-worker resolution', () => {
  let dir: string;
  let prevCwd: string | undefined;

  beforeEach(() => {
    dir = mkdtempSync(join(tmpdir(), 'ruflo-1916-'));
    prevCwd = process.env.CLAUDE_FLOW_CWD;
    process.env.CLAUDE_FLOW_CWD = dir;
    // hive-mind_spawn writes here:
    mkdirSync(join(dir, '.claude-flow'), { recursive: true });
    writeFileSync(
      join(dir, '.claude-flow', 'agents.json'),
      JSON.stringify({
        agents: {
          'hive-worker-1716-abcd': {
            agentId: 'hive-worker-1716-abcd',
            agentType: 'worker',
            status: 'idle',
            health: 1.0,
            taskCount: 0,
            config: { role: 'worker', hiveRole: 'worker' },
            createdAt: '2026-05-11T00:00:00.000Z',
            domain: 'hive-mind',
          },
        },
      }),
    );
  });

  afterEach(() => {
    if (prevCwd === undefined) delete process.env.CLAUDE_FLOW_CWD;
    else process.env.CLAUDE_FLOW_CWD = prevCwd;
    rmSync(dir, { recursive: true, force: true });
  });

  it('(a) agent_logs is a registered MCP tool', () => {
    expect(agentTools.some(t => t.name === 'agent_logs')).toBe(true);
  });

  it('(a) agent_logs returns the documented shape for an unknown agent (no throw)', async () => {
    const res = await (tool('agent_logs').handler as any)({ agentId: 'agent-does-not-exist' });
    expect(res).toMatchObject({ agentId: 'agent-does-not-exist', entries: [], total: 0, error: 'Agent not found' });
  });

  it('(b) agent_status resolves a hive-mind-spawned worker', async () => {
    const res = await (tool('agent_status').handler as any)({ agentId: 'hive-worker-1716-abcd' });
    expect(res.status).not.toBe('not_found');
    expect(res).toMatchObject({ agentId: 'hive-worker-1716-abcd', agentType: 'worker', status: 'idle' });
  });

  it('(b) agent_list includes hive-mind-spawned workers', async () => {
    const res = await (tool('agent_list').handler as any)({});
    expect(res.agents.map((a: any) => a.agentId)).toContain('hive-worker-1716-abcd');
  });

  it('(b) agent_logs resolves a hive-mind-spawned worker and returns entries', async () => {
    const res = await (tool('agent_logs').handler as any)({ agentId: 'hive-worker-1716-abcd' });
    expect(res.error).toBeUndefined();
    expect(res.agentId).toBe('hive-worker-1716-abcd');
    expect(Array.isArray(res.entries)).toBe(true);
    expect(res.entries.length).toBeGreaterThan(0); // at least the synthetic "agent created" entry
  });

  it('canonical store wins on id collision', async () => {
    // Same id in the canonical store with a richer record:
    mkdirSync(join(dir, '.claude-flow', 'agents'), { recursive: true });
    writeFileSync(
      join(dir, '.claude-flow', 'agents', 'store.json'),
      JSON.stringify({
        version: '3.0.0',
        agents: {
          'hive-worker-1716-abcd': {
            agentId: 'hive-worker-1716-abcd',
            agentType: 'coder',
            status: 'busy',
            health: 0.9,
            taskCount: 3,
            config: {},
            createdAt: '2026-05-11T01:00:00.000Z',
          },
        },
      }),
    );
    const res = await (tool('agent_status').handler as any)({ agentId: 'hive-worker-1716-abcd' });
    expect(res).toMatchObject({ agentType: 'coder', status: 'busy', taskCount: 3 });
  });
});

/**
 * Tests for agentbbs MCP tools (ADR-164 Phase 1).
 *
 * Two surfaces under test:
 *   1. STRUCTURAL — exposure, schema, validation. Runs regardless of agentbbs presence.
 *   2. HAPPY PATH — gated on agentbbs being importable via it.skipIf(!havePkg).
 *
 * The degraded path is exercised structurally: when agentbbs is missing,
 * every handler returns `{degraded: true, reason: 'agentbbs-not-found'}`
 * matching the metaharness / agenticow / testgen contract.
 */
import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import { mkdtempSync, rmSync, existsSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { tmpdir } from 'node:os';

import { agentbbsTools } from '../src/mcp-tools/agentbbs-tools.js';

function findTool(name: string) {
  const t = agentbbsTools.find(t => t.name === name);
  if (!t) throw new Error(`tool not found: ${name}`);
  return t;
}

// Detect agentbbs availability at module scope so it.skipIf evaluates correctly.
let havePkg = false;
try { await import('agentbbs'); havePkg = true; } catch { havePkg = false; }

describe('agentbbs MCP tools — structural contract', () => {
  it('exposes exactly 4 tools (register / publish / watch / human_join)', () => {
    const names = agentbbsTools.map(t => t.name).sort();
    expect(names).toEqual([
      'federation_bbs_human_join',
      'federation_bbs_publish',
      'federation_bbs_register',
      'federation_bbs_watch',
    ]);
  });

  it('every tool has an object inputSchema with handler + ≥80-char description', () => {
    for (const t of agentbbsTools) {
      expect(t.inputSchema.type).toBe('object');
      expect(t.inputSchema.properties).toBeDefined();
      expect(typeof t.handler).toBe('function');
      expect(t.description.length).toBeGreaterThanOrEqual(80);
      // ADR-112 — descriptions must carry "Use when ... is wrong because ..." guidance.
      expect(t.description).toMatch(/Use when/i);
      expect(t.description).toMatch(/wrong because/i);
    }
  });

  it('register rejects path traversal in basePath', async () => {
    const register = findTool('federation_bbs_register');
    await expect(register.handler({
      basePath: '../../../../etc/passwd',
      roomLabel: '#sales',
    })).rejects.toThrow(/disallowed characters/);
  });

  it('register rejects an illegal roomLabel', async () => {
    const register = findTool('federation_bbs_register');
    await expect(register.handler({
      roomLabel: 'evil; rm -rf /',
    })).rejects.toThrow(/may only contain/);
  });

  it('register accepts conventional #-prefixed room labels', async () => {
    // Even when agentbbs is missing we should validate inputs first OR degrade
    // — but the contract is: validation errors must surface as throws.
    // With agentbbs missing we get a degraded result instead of validation.
    // So this test only meaningfully covers regex acceptance shape.
    expect(/^[A-Za-z0-9_.\-:/@#]+$/.test('#sales')).toBe(true);
    expect(/^[A-Za-z0-9_.\-:/@#]+$/.test('finance')).toBe(true);
    expect(/^[A-Za-z0-9_.\-:/@#]+$/.test('hr/onboarding')).toBe(true);
  });

  it('publish rejects malformed msgType (validation runs before optional-dep check)', async () => {
    const publish = findTool('federation_bbs_publish');
    await expect(publish.handler({
      roomId: 'sales-12345678',
      msgType: 'bad type with spaces',
      payload: {},
    })).rejects.toThrow(/msgType must be alnum/);
  });

  it('publish rejects non-object payload', async () => {
    const publish = findTool('federation_bbs_publish');
    await expect(publish.handler({
      roomId: 'sales-12345678',
      msgType: 'task-result',
      payload: 'not an object',
    })).rejects.toThrow(/payload must be a JSON object/);
  });

  it('all 4 tools return {degraded:true, reason:"agentbbs-not-found"} when agentbbs is missing', async () => {
    if (havePkg) return; // happy-path case is covered elsewhere
    for (const t of agentbbsTools) {
      const minimalInput: Record<string, unknown> =
        t.name === 'federation_bbs_register'    ? { roomLabel: '#sales' } :
        t.name === 'federation_bbs_publish'     ? { roomId: 'sales-12345678', msgType: 'task-result', payload: {} } :
        t.name === 'federation_bbs_watch'       ? { roomId: 'sales-12345678' } :
        t.name === 'federation_bbs_human_join'  ? { roomId: 'sales-12345678' } :
        {};
      const r: any = await t.handler(minimalInput);
      expect(r.success).toBe(true);
      expect(r.degraded).toBe(true);
      expect(r.reason).toBe('agentbbs-not-found');
    }
  });
});

describe('agentbbs MCP tools — happy path (real package)', () => {
  let workdir: string;
  let roomId: string;

  beforeAll(() => {
    workdir = mkdtempSync(join(tmpdir(), 'agentbbs-tools-'));
  });

  afterAll(() => {
    try { rmSync(workdir, { recursive: true, force: true }); } catch { /* ignore */ }
  });

  it.skipIf(!havePkg)('register: creates a room and persists registry', async () => {
    const register = findTool('federation_bbs_register');
    const r: any = await register.handler({ basePath: workdir, roomLabel: '#sales' });
    expect(r.success).toBe(true);
    expect(r.degraded).toBeUndefined();
    expect(r.trustLevel).toBe('attested');
    expect(r.roomId).toMatch(/^sales-[0-9a-f]{8}$/);
    expect(r.nodeId).toMatch(/^[0-9a-f]{16}$/);
    roomId = r.roomId;
    const reg = JSON.parse(readFileSync(join(workdir, 'rooms.json'), 'utf-8'));
    expect(reg[roomId]).toBeDefined();
    expect(reg[roomId].roomLabel).toBe('#sales');
  });

  it.skipIf(!havePkg)('publish: writes a ReplicateMessage envelope to the room log', async () => {
    const publish = findTool('federation_bbs_publish');
    const r: any = await publish.handler({
      basePath: workdir,
      roomId,
      msgType: 'task-result',
      payload: { agent: 'lead-gen', leadsQualified: 3 },
    });
    expect(r.success).toBe(true);
    expect(r.degraded).toBeUndefined();
    expect(r.envelopeId).toBeTruthy();
    expect(r.recipientHopCount).toBe(0);
    expect(existsSync(join(workdir, `room-${roomId}.jsonl`))).toBe(true);
  });

  it.skipIf(!havePkg)('watch: returns envelopes from the room log with monotonic seq', async () => {
    const watch = findTool('federation_bbs_watch');
    const r: any = await watch.handler({ basePath: workdir, roomId, limit: 50 });
    expect(r.success).toBe(true);
    expect(r.envelopes.length).toBeGreaterThan(0);
    // Seq must be strictly monotonic
    let lastSeq = 0;
    for (const e of r.envelopes) {
      expect(e.seq).toBeGreaterThan(lastSeq);
      lastSeq = e.seq;
    }
  });

  it.skipIf(!havePkg)('human_join: mints a single-use Ed25519-signed token that expires in the future', async () => {
    const join = findTool('federation_bbs_human_join');
    const before = Date.now();
    const r: any = await join.handler({ roomId: 'sales-12345678', ttlSeconds: 120 });
    const after = Date.now();
    expect(r.success).toBe(true);
    expect(r.degraded).toBeUndefined();
    expect(r.handshakeToken).toBeTruthy();
    expect(r.handshakeToken.length).toBeGreaterThan(50);
    expect(r.webUrl).toMatch(/^https:\/\/agentbbs\.local\//);
    expect(r.sshCommand).toMatch(/^ssh /);
    const expiresAt = new Date(r.expiresAt).getTime();
    expect(expiresAt).toBeGreaterThan(before);
    // Expiry must be ≤ ttlSeconds from now (within a wide margin to absorb scheduling jitter).
    expect(expiresAt - after).toBeLessThanOrEqual(120 * 1000 + 1000);
    expect(expiresAt - before).toBeGreaterThanOrEqual(120 * 1000 - 1000);
  });
});

/**
 * agentdb_*-delete MCP tool surface tests (#1784).
 *
 * Verifies the three new delete tools exist, validate inputs, and surface
 * the right shapes for both supported (SQL fallback) and unsupported
 * (native graph-node / HierarchicalMemory) backends.
 *
 * Behavioral integration tests (actually deleting rows from a live
 * AgentDB) are out of scope here — they require a sqlite + agentdb
 * instance which the cli's existing test scaffolding doesn't spin up
 * for unit tests. The MCP-level shape tests below cover the contract
 * the importer (plugins/ruflo-adr/scripts/import.mjs) depends on.
 */

import { describe, expect, it } from 'vitest';
import {
  agentdbHierarchicalDelete,
  agentdbCausalEdgeDelete,
  agentdbCausalNodeDelete,
  agentdbTools,
} from '../src/mcp-tools/agentdb-tools.js';

describe('agentdb delete tools — surface (#1784)', () => {
  it('exposes agentdb_hierarchical-delete in the tool registry', () => {
    const names = agentdbTools.map((t) => t.name);
    expect(names).toContain('agentdb_hierarchical-delete');
  });

  it('exposes agentdb_causal-edge-delete in the tool registry', () => {
    const names = agentdbTools.map((t) => t.name);
    expect(names).toContain('agentdb_causal-edge-delete');
  });

  it('exposes agentdb_causal-node-delete in the tool registry', () => {
    const names = agentdbTools.map((t) => t.name);
    expect(names).toContain('agentdb_causal-node-delete');
  });

  it('hierarchical-delete validates required key parameter', async () => {
    const r = await agentdbHierarchicalDelete.handler({});
    expect(r.success).toBe(false);
    expect(r.deleted).toBe(false);
    expect(typeof r.error).toBe('string');
  });

  it('hierarchical-delete rejects invalid tier', async () => {
    const r = await agentdbHierarchicalDelete.handler({
      key: 'test-key',
      tier: 'not-a-real-tier',
    });
    expect(r.success).toBe(false);
    expect(r.error).toMatch(/tier|Invalid|disallowed/i);
  });

  it('hierarchical-delete accepts valid tiers', async () => {
    for (const tier of ['working', 'episodic', 'semantic']) {
      const r = await agentdbHierarchicalDelete.handler({ key: 'test-key', tier });
      // Either it works (success) or it surfaces a controller status — both are fine
      expect(r).toBeDefined();
      expect(typeof r.success).toBe('boolean');
    }
  });

  it('causal-edge-delete validates required sourceId / targetId', async () => {
    const r1 = await agentdbCausalEdgeDelete.handler({ targetId: 'B' });
    expect(r1.success).toBe(false);
    const r2 = await agentdbCausalEdgeDelete.handler({ sourceId: 'A' });
    expect(r2.success).toBe(false);
  });

  it('causal-edge-delete handles a missing edge cleanly (returns native-unsupported or not-found)', async () => {
    const r = await agentdbCausalEdgeDelete.handler({
      sourceId: 'nonexistent-source',
      targetId: 'nonexistent-target',
    });
    expect(r).toBeDefined();
    expect(typeof r.success).toBe('boolean');
    // If the bridge isn't available at all, the tool surfaces an error;
    // if it is, controller will be 'native-unsupported' or 'sql-error'.
    if (r.controller) {
      expect(['native-unsupported', 'bridge-fallback', 'sql-error', 'guard']).toContain(r.controller);
    }
  });

  it('causal-node-delete validates required nodeId', async () => {
    const r = await agentdbCausalNodeDelete.handler({});
    expect(r.success).toBe(false);
    expect(r.deletedNode).toBe(false);
    expect(r.deletedEdges).toBe(0);
  });

  it('causal-node-delete returns the cascade contract shape', async () => {
    const r = await agentdbCausalNodeDelete.handler({ nodeId: 'nonexistent-node' });
    expect(r).toBeDefined();
    expect(typeof r.success).toBe('boolean');
    expect(typeof r.deletedNode).toBe('boolean');
    expect(typeof r.deletedEdges).toBe('number');
    // nodeId is echoed back when the bridge returns a real result. When the
    // bridge isn't available (test env without AgentDB), the handler returns
    // its no-bridge fallback shape without nodeId — both are valid.
    if (r.nodeId !== undefined) {
      expect(r.nodeId).toBe('nonexistent-node');
    } else {
      expect(r.error).toMatch(/bridge not available/i);
    }
  });

  it('all three delete tools have an inputSchema with required fields', () => {
    for (const tool of [agentdbHierarchicalDelete, agentdbCausalEdgeDelete, agentdbCausalNodeDelete]) {
      expect(tool.inputSchema.type).toBe('object');
      expect(Array.isArray(tool.inputSchema.required)).toBe(true);
      expect((tool.inputSchema.required as string[]).length).toBeGreaterThan(0);
    }
  });

  it('all three delete tools return useful descriptions surfacing the native-backend caveat', () => {
    expect(agentdbHierarchicalDelete.description).toMatch(/native|backend|delete/i);
    expect(agentdbCausalEdgeDelete.description).toMatch(/native|backend|delete/i);
    expect(agentdbCausalNodeDelete.description).toMatch(/cascade|delete/i);
  });
});

/**
 * Tests for agenticow MCP tools.
 *
 * Two surfaces under test:
 *   1. The HAPPY PATH — agenticow is installed (real package). The tool round-trips
 *      through actual COW branch / checkpoint / rollback / promote semantics on
 *      a temp .rvf file.
 *   2. The DEGRADED PATH — agenticow is NOT installed (we vi.mock() it as
 *      ERR_MODULE_NOT_FOUND). Every tool must return `{degraded: true}` with no
 *      throw, matching the metaharness-tools / testgen-tools contract.
 *
 * Why both: agenticow is in `optionalDependencies`. CI runs with deps installed
 * (happy path) but production users may not have it — the degraded path is
 * the load-bearing architectural rule (zero hard runtime dep).
 */
import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import { mkdtempSync, rmSync, existsSync, statSync, readdirSync } from 'node:fs';
import { join } from 'node:path';
import { tmpdir } from 'node:os';

import { agenticowTools } from '../src/mcp-tools/agenticow-tools.js';

function findTool(name: string) {
  const t = agenticowTools.find(t => t.name === name);
  if (!t) throw new Error(`tool not found: ${name}`);
  return t;
}

function dirBytes(p: string): number {
  if (!existsSync(p)) return 0;
  const st = statSync(p);
  if (st.isFile()) return st.size;
  let total = 0;
  for (const e of readdirSync(p)) total += dirBytes(join(p, e));
  return total;
}

// Detect agenticow availability at module scope (top-level await is allowed
// in vitest ESM modules). We need this before the `it.skipIf(...)` calls,
// which evaluate at definition time.
let havePkg = false;
try { await import('agenticow'); havePkg = true; } catch { havePkg = false; }

describe('agenticow MCP tools — happy path (real package)', () => {
  let workdir: string;
  let basePath: string;

  beforeAll(() => {
    workdir = mkdtempSync(join(tmpdir(), 'agenticow-tools-'));
    basePath = join(workdir, 'base.rvf');
  });

  afterAll(() => {
    try { rmSync(workdir, { recursive: true, force: true }); } catch { /* ignore */ }
  });

  it('exposes exactly 4 tools (branch / checkpoint / rollback / promote)', () => {
    const names = agenticowTools.map(t => t.name).sort();
    expect(names).toEqual([
      'agenticow_branch',
      'agenticow_checkpoint',
      'agenticow_promote',
      'agenticow_rollback',
    ]);
  });

  it('every tool has a JSON-schema input + handler', () => {
    for (const t of agenticowTools) {
      expect(t.inputSchema.type).toBe('object');
      expect(t.inputSchema.properties).toBeDefined();
      expect(typeof t.handler).toBe('function');
    }
  });

  it.skipIf(!havePkg)('agenticow_branch creates a tiny COW branch on a real base', async () => {
    const branch = findTool('agenticow_branch');
    // Use a small dim for test speed
    const branchPath = join(workdir, 'b1.rvf');
    const result: any = await branch.handler({
      basePath, branchPath,
      label: 'test-branch',
      dimension: 32,
    });
    expect(result.success).toBe(true);
    expect(result.degraded).toBeUndefined();
    expect(result.label).toBe('test-branch');
    expect(existsSync(branchPath)).toBe(true);
    // The size win is the load-bearing claim — assert it's tiny
    expect(dirBytes(branchPath)).toBeLessThan(2048);
  });

  it.skipIf(!havePkg)('agenticow_checkpoint persists state across reopen, agenticow_rollback restores it', async () => {
    const cp = findTool('agenticow_checkpoint');
    const rb = findTool('agenticow_rollback');

    // checkpoint must persist via the .agenticow.json manifest. The base file
    // was created earlier by the branch test (which writes the manifest).
    const cpResult: any = await cp.handler({ path: basePath, label: 'cp-1' });
    expect(cpResult.success).toBe(true);
    expect(cpResult.label).toBe('cp-1');
    // Manifest file should now exist next to the .rvf
    expect(existsSync(`${basePath}.agenticow.json`)).toBe(true);

    // Rollback now finds the checkpoint via the persisted manifest
    const rbResult: any = await rb.handler({ path: basePath });
    expect(rbResult.success).toBe(true);
    expect(rbResult.rolledBack).toBe(true);
  });

  it('agenticow_branch rejects path traversal in basePath', async () => {
    const branch = findTool('agenticow_branch');
    await expect(branch.handler({
      basePath: '../../../../etc/passwd',
      branchPath: join(workdir, 'evil.rvf'),
      label: 'evil',
      dimension: 32,
    })).rejects.toThrow(/disallowed characters/);
  });

  it('agenticow_branch rejects a malformed label', async () => {
    const branch = findTool('agenticow_branch');
    await expect(branch.handler({
      basePath,
      branchPath: join(workdir, 'b2.rvf'),
      label: 'evil; rm -rf /',
      dimension: 32,
    })).rejects.toThrow(/may only contain/);
  });

  it('agenticow_branch requires dimension when creating a new memory file', async () => {
    const branch = findTool('agenticow_branch');
    const freshBase = join(workdir, 'nonexistent.rvf');
    await expect(branch.handler({
      basePath: freshBase,
      branchPath: join(workdir, 'b3.rvf'),
      label: 'fresh',
      // no dimension
    })).rejects.toThrow(/dimension is required/);
  });
});

/**
 * Tests for AtomicBbsRoomBudgetTracker — ADR-164.1.
 *
 * Implements Tests 1, 2, 3, 6 from §9. Test 4 (mid-transaction crash) is
 * covered by a synchronous throw-during-reserve scenario; Test 5 (clock-skew
 * backward) is intentionally skipped as it requires system-clock control
 * beyond what the test harness exposes — see ADR-164.1 §9 Test 5 for the
 * design intent.
 *
 * Uses better-sqlite3 in-memory mode for speed.
 */
import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { createRequire } from 'node:module';

import {
  AtomicBbsRoomBudgetTracker,
  clampReservationExpiry,
  RESERVATION_EXPIRY_FLOOR_MS,
  RESERVATION_EXPIRY_CEILING_MS,
  createAtomicTrackerIfEnabled,
  type BudgetAuditSink,
  type SqliteDatabase,
} from '../src/business-pods/bbs-budget-tracker.js';

// Resolve better-sqlite3 via CJS require so tests work even when ESM
// resolution from this nested test depth has trouble locating the
// hoisted v3-level dependency.
const cjsRequire = createRequire(import.meta.url);
type DatabaseCtor = new (filename: string) => SqliteDatabase;

function openDb(): SqliteDatabase {
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  const Database = cjsRequire('better-sqlite3') as DatabaseCtor;
  return new Database(':memory:');
}

let db: SqliteDatabase;
let auditEvents: Array<{ type: string; payload: Record<string, unknown> }>;
let audit: BudgetAuditSink;

beforeEach(() => {
  db = openDb();
  auditEvents = [];
  audit = {
    emit: (type, payload) => { auditEvents.push({ type, payload }); },
  };
});

afterEach(() => {
  try { db.close(); } catch { /* noop */ }
});

// ---------- clamp ---------------------------------------------------------

describe('clampReservationExpiry', () => {
  it('clamps small values up to the 5s floor', () => {
    expect(clampReservationExpiry(1000)).toBe(RESERVATION_EXPIRY_FLOOR_MS);
  });
  it('clamps large values down to the 5min ceiling', () => {
    expect(clampReservationExpiry(60 * 60 * 1000)).toBe(RESERVATION_EXPIRY_CEILING_MS);
  });
  it('passes through values within bounds', () => {
    expect(clampReservationExpiry(30_000)).toBe(30_000);
  });
});

// ---------- Test 1: serial reserves under a cap (drop-in for §9 Test 1) --

describe('Test 1 — serial reserves under a $1.00 cap', () => {
  it('exactly 20 of 100 callers reserving $0.05 succeed; 80 BUDGET_EXCEEDED; total = $1.00', () => {
    const tracker = new AtomicBbsRoomBudgetTracker({ db, audit, defaultExpiryMs: 60_000 });
    tracker.registerRoom('sales-test', 1.0);

    let ok = 0;
    let exceeded = 0;
    for (let i = 0; i < 100; i++) {
      const r = tracker.reserve('sales-test', `caller-${i}`, 0.05);
      if (r.ok) ok++;
      else if (r.error === 'BUDGET_EXCEEDED') exceeded++;
    }
    expect(ok).toBe(20);
    expect(exceeded).toBe(80);

    const rows = tracker.listReservations('sales-test').filter((r) => r.state === 'reserved');
    expect(rows.length).toBe(20);
    const sum = rows.reduce((acc, r) => acc + Number(r.estimated_usd), 0);
    expect(sum).toBeCloseTo(1.0, 6);
  });
});

// ---------- Test 2: block → release → allow 10 of 50 ---------------------

describe('Test 2 — release frees budget for subsequent callers', () => {
  it('first $0.50 reserve blocks 50 callers; release frees 10 of next 50', () => {
    const tracker = new AtomicBbsRoomBudgetTracker({ db, audit, defaultExpiryMs: 60_000 });
    tracker.registerRoom('sales-test2', 1.0);

    const initial = tracker.reserve('sales-test2', 'initial', 0.5);
    expect(initial.ok).toBe(true);
    if (!initial.ok) throw new Error('unreachable');
    const reservationIdA = initial.reservationId;

    // Step B: 50 reserves of $0.05 — all should fail (0.50 + 0.05 = 0.55 OK
    // for the first call, but cumulative reserved + 0.05 must exceed cap to fail).
    // 0.50 reserved + 50 × 0.05 = 0.50 + 2.50 = 3.00 way over. Each individual
    // call sees 0.50 + N×0.05 already reserved, so callers 1-10 succeed and
    // 11-50 fail (0.50 reserved + 0.50 in step B = 1.00 cap reached after 10).
    let phaseBOk = 0;
    let phaseBFail = 0;
    for (let i = 0; i < 50; i++) {
      const r = tracker.reserve('sales-test2', `phaseB-${i}`, 0.05);
      if (r.ok) phaseBOk++;
      else phaseBFail++;
    }
    expect(phaseBOk).toBe(10);
    expect(phaseBFail).toBe(40);

    // Step C: release the initial $0.50.
    const rel = tracker.release(reservationIdA);
    expect(rel.ok).toBe(true);

    // Step D: another 50 — should see exactly 10 succeed (0.50 freed → 10 × 0.05).
    let phaseDOk = 0;
    let phaseDFail = 0;
    for (let i = 0; i < 50; i++) {
      const r = tracker.reserve('sales-test2', `phaseD-${i}`, 0.05);
      if (r.ok) phaseDOk++;
      else phaseDFail++;
    }
    expect(phaseDOk).toBe(10);
    expect(phaseDFail).toBe(40);
  });
});

// ---------- Test 3: expiry frees budget after sweepExpired() --------------

describe('Test 3 — expiry frees budget for next caller', () => {
  it('after sweepExpired() an expired reservation no longer blocks new reserves', () => {
    let mockNow = 1_000_000;
    const tracker = new AtomicBbsRoomBudgetTracker({
      db, audit,
      defaultExpiryMs: 5_000, // floor — clamp goes to 5000ms
      clock: () => mockNow,
    });
    tracker.registerRoom('hr-test', 0.10);

    const a = tracker.reserve('hr-test', 'agent-1', 0.10);
    expect(a.ok).toBe(true);

    // Step B: should be BUDGET_EXCEEDED (live reservation occupies full cap).
    const b = tracker.reserve('hr-test', 'agent-2', 0.05);
    expect(b.ok).toBe(false);
    if (b.ok) throw new Error('unreachable');
    expect(b.error).toBe('BUDGET_EXCEEDED');

    // Step C: advance clock past expiry, then sweep.
    mockNow += 6_000;
    const swept = tracker.sweepExpired();
    expect(swept).toBe(1);

    // Step D: next reserve succeeds (the expired row is excluded from totals).
    const d = tracker.reserve('hr-test', 'agent-2', 0.05);
    expect(d.ok).toBe(true);
  });

  it('expired reservation is excluded from gate check BEFORE sweep (window query check)', () => {
    let mockNow = 2_000_000;
    const tracker = new AtomicBbsRoomBudgetTracker({
      db, audit,
      defaultExpiryMs: 5_000,
      clock: () => mockNow,
    });
    tracker.registerRoom('window-test', 0.10);

    const a = tracker.reserve('window-test', 'agent-1', 0.10);
    expect(a.ok).toBe(true);

    // Advance past expiry but DO NOT call sweepExpired().
    mockNow += 6_000;

    // Per ADR-164.1 §7.2 "phantom debt intentional bias" — even unswepped
    // expired rows must be excluded from the reserve() gate check.
    const b = tracker.reserve('window-test', 'agent-2', 0.05);
    expect(b.ok).toBe(true);
  });
});

// ---------- Test 6: COMMIT_AFTER_EXPIRY closes Expired Commit Leak --------

describe('Test 6 — COMMIT_AFTER_EXPIRY captures the real spend (§8.1 fix)', () => {
  it('late commit records spend, marks committed_post_expiry, emits audit', () => {
    let mockNow = 3_000_000;
    const tracker = new AtomicBbsRoomBudgetTracker({
      db, audit,
      defaultExpiryMs: 5_000,
      clock: () => mockNow,
    });
    tracker.registerRoom('commit-late', 1.0);

    const r = tracker.reserve('commit-late', 'agent-1', 0.30);
    expect(r.ok).toBe(true);
    if (!r.ok) throw new Error('unreachable');
    const reservationId = r.reservationId;

    // Advance past expiry — reservation is now expired but not committed.
    mockNow += 6_000;

    // Late commit: should succeed with warned: 'COMMIT_AFTER_EXPIRY'.
    const c = tracker.commit(reservationId, 0.30);
    expect(c.ok).toBe(true);
    if (!c.ok) throw new Error('unreachable');
    expect('warned' in c && c.warned).toBe('COMMIT_AFTER_EXPIRY');
    if ('warned' in c) {
      expect(c.finalRemaining).toBeCloseTo(0.70, 6);
    }

    // Audit emitted the high-priority envelope.
    const evt = auditEvents.find((e) => e.type === 'reservation.committed_post_expiry');
    expect(evt).toBeDefined();
    expect(evt!.payload.reservationId).toBe(reservationId);

    // The post-expiry commit counts against the budget.
    const next = tracker.reserve('commit-late', 'agent-2', 0.70);
    expect(next.ok).toBe(true);

    // Now fully spent — even a tiny additional reserve is BUDGET_EXCEEDED.
    const tiny = tracker.reserve('commit-late', 'agent-3', 0.01);
    expect(tiny.ok).toBe(false);
    if (tiny.ok) throw new Error('unreachable');
    expect(tiny.error).toBe('BUDGET_EXCEEDED');
  });

  it('happy-path commit (within window) returns committed:true without warning', () => {
    const tracker = new AtomicBbsRoomBudgetTracker({ db, audit, defaultExpiryMs: 60_000 });
    tracker.registerRoom('commit-clean', 1.0);
    const r = tracker.reserve('commit-clean', 'agent-1', 0.20);
    expect(r.ok).toBe(true);
    if (!r.ok) throw new Error('unreachable');

    const c = tracker.commit(r.reservationId, 0.18);
    expect(c.ok).toBe(true);
    if (!c.ok) throw new Error('unreachable');
    expect('committed' in c && c.committed).toBe(true);
    if ('committed' in c) {
      expect(c.finalRemaining).toBeCloseTo(0.82, 6);
    }
  });

  it('double-commit returns ALREADY_FINALIZED', () => {
    const tracker = new AtomicBbsRoomBudgetTracker({ db, audit, defaultExpiryMs: 60_000 });
    tracker.registerRoom('double-commit', 1.0);
    const r = tracker.reserve('double-commit', 'agent-1', 0.10);
    if (!r.ok) throw new Error('expected ok');
    expect(tracker.commit(r.reservationId, 0.10).ok).toBe(true);
    const second = tracker.commit(r.reservationId, 0.05);
    expect(second.ok).toBe(false);
    if (second.ok) throw new Error('unreachable');
    expect(second.error).toBe('ALREADY_FINALIZED');
  });

  it('commit on unknown id returns NOT_FOUND', () => {
    const tracker = new AtomicBbsRoomBudgetTracker({ db, audit });
    const c = tracker.commit('does-not-exist', 0.10);
    expect(c.ok).toBe(false);
    if (c.ok) throw new Error('unreachable');
    expect(c.error).toBe('NOT_FOUND');
  });

  it('release on committed reservation returns ALREADY_FINALIZED', () => {
    const tracker = new AtomicBbsRoomBudgetTracker({ db, audit, defaultExpiryMs: 60_000 });
    tracker.registerRoom('release-blocked', 1.0);
    const r = tracker.reserve('release-blocked', 'agent-1', 0.10);
    if (!r.ok) throw new Error('expected ok');
    expect(tracker.commit(r.reservationId, 0.10).ok).toBe(true);
    const rel = tracker.release(r.reservationId);
    expect(rel.ok).toBe(false);
    if (rel.ok) throw new Error('unreachable');
    expect(rel.error).toBe('ALREADY_FINALIZED');
  });

  it('reserve on unknown room returns ROOM_NOT_FOUND', () => {
    const tracker = new AtomicBbsRoomBudgetTracker({ db, audit });
    const r = tracker.reserve('no-such-room', 'agent-1', 0.10);
    expect(r.ok).toBe(false);
    if (r.ok) throw new Error('unreachable');
    expect(r.error).toBe('ROOM_NOT_FOUND');
  });
});

