          edges: [],
          metadata: { rootDir: '/test', totalFiles: 1, totalEdges: 0, buildTime: 5 },
        },
        circularDependencies: [],
        statistics: { nodeCount: 1, edgeCount: 0, avgDegree: 0, maxDegree: 0, density: 0, componentCount: 1 },
