  });

  it('should validate IPNS domain', () => {
    expect(isValidIPNS('example.com')).toBe(true);
  });

  it('should reject invalid IPNS', () => {
    expect(isValidIPNS('')).toBe(false);
  });

  it('should generate gateway URL', () => {
