      if (c) {
        if (d) {
          while (e) {
            for (let i = 0; i < 10; i++) {
              try {
                switch (f) {
                  case 1: break;
                  case 2: break;
                  default: throw new Error();
                }
              } catch (err) {
                console.error(err);
              }
            }
          }
        }
