import { EventEmitter } from 'events';
import type { ChildProcess } from 'child_process';

// Mock modules before imports
vi.mock('child_process', () => ({
  spawn: vi.fn(),
  execSync: vi.fn(),
}));

vi.mock('glob', () => ({
  glob: vi.fn(),
  globSync: vi.fn(),
}));

